def kmp_search(text: str, pattern: str) -> int:
    if not pattern:
        return 0
    if not text:
        return -1

    # Build LPS (Longest Prefix Suffix) array
    lps = [0] * len(pattern)
    length = 0  # length of previous longest prefix suffix
    i = 1
    while i < len(pattern):
        if pattern[i] == pattern[length]:
            length += 1
            lps[i] = length
            i += 1
        else:
            if length != 0:
                length = lps[length - 1]
            else:
                lps[i] = 0
                i += 1

    # Search for pattern in text
    i = j = 0  # i for text, j for pattern
    while i < len(text):
        if text[i] == pattern[j]:
            i += 1
            j += 1
            if j == len(pattern):
                return i - j  # Match found
        else:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1
    return -1
