def find_cycle_nodes(graph):
    """
    Detects a cycle in a directed graph and returns the nodes in the cycle.
    graph: dict where keys are nodes and values are lists of adjacent nodes.
    Returns: list of nodes forming the cycle or [] if no cycle exists.
    """
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {node: WHITE for node in graph}

    def dfs(node, path):
        color[node] = GRAY
        path.append(node)

        for neighbor in graph.get(node, []):
            if neighbor not in color:
                color[neighbor] = WHITE
            if color[neighbor] == GRAY:
                # Cycle detected
                cycle_start = path.index(neighbor)
                return path[cycle_start:]
            if color[neighbor] == WHITE:
                result = dfs(neighbor, path)
                if result:
                    return result

        path.pop()
        color[node] = BLACK
        return []

    for node in graph:
        if color[node] == WHITE:
            return dfs(node, [])
    return []
